<template><div class="ops-page"><HeaderBar /><main class="ops-main"><div class="ops-toolbar"><div><span class="ops-eyebrow">FIRMWARE RELEASES</span><h1>固件发布</h1><p class="ops-lead">新版本先准备构建产物与摘要，再由独立人员批准发布。已发布记录不覆盖。</p></div><el-button v-if="can('ota.upload') && can('ota.publish')" type="primary" @click="open">准备新版本</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false" /><section class="ops-panel"><h2>发布申请</h2><el-table :data="approvals" empty-text="暂无固件发布申请"><el-table-column prop="targetId" label="硬件类型" /><el-table-column prop="version" label="版本" /><el-table-column prop="status" label="状态" /><el-table-column prop="payloadHash" label="审批内容摘要" show-overflow-tooltip /><el-table-column label="操作"><template slot-scope="s"><el-button v-if="s.row.status === 'APPROVED' && s.row.requesterId === $store.state.userInfo.employeeId && can('ota.publish')" type="text" :disabled="busy" @click="publish(s.row)">发布批准版本</el-button><el-button v-else-if="s.row.status === 'PENDING'" type="text" @click="$router.push('/approvals')">前往审批</el-button></template></el-table-column></el-table></section><section class="ops-panel"><div class="ops-toolbar"><h2>已发布版本</h2><el-button size="small" :loading="loading" @click="load">刷新</el-button></div><el-table :data="rows" v-loading="loading"><el-table-column prop="firmwareName" label="固件" min-width="180" /><el-table-column prop="type" label="硬件类型" min-width="130" /><el-table-column prop="version" label="版本" width="110" /><el-table-column prop="remark" label="说明" min-width="180" /></el-table><el-pagination :current-page="page" :total="total" :page-size="20" layout="total, prev, pager, next" @current-change="changePage" /></section><el-dialog title="准备新固件版本" :visible.sync="dialog" width="min(570px,94vw)" :close-on-click-modal="false"><el-form label-width="105px"><el-form-item label="固件名称"><el-input v-model="form.firmwareName" /></el-form-item><el-form-item label="硬件类型"><el-input v-model="form.type" placeholder="与设备实际硬件类型匹配的标识" /></el-form-item><el-form-item label="版本"><el-input v-model="form.version" placeholder="例如 1.2.3" /></el-form-item><el-form-item label="构建产物"><input ref="firmwareFile" type="file" accept=".bin,.apk" :disabled="busy" @change="chooseFile" /><p class="ops-muted">不超过 100 MB；服务端计算并锁定文件摘要。</p></el-form-item><el-form-item label="发布说明"><el-input v-model="form.remark" type="textarea" :rows="3" /></el-form-item></el-form><el-alert v-if="saveError" :title="saveError" type="error" :closable="false" /><span slot="footer"><el-button :disabled="busy" @click="dialog=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!file" @click="prepare">上传并申请审批</el-button></span></el-dialog></main></div></template>
<script>
import HeaderBar from '@/components/HeaderBar.vue';
import { platformRequest } from '@/apis/platform';
import { hasPermission } from '@/security/session';
export default {
  components: { HeaderBar }, data() { return { rows: [], approvals: [], loading: false, busy: false, error: '', page: 1, total: 0, dialog: false, file: null, saveError: '', form: { firmwareName: '', type: '', version: '', firmwarePath: '', remark: '', sort: 0 } }; },
  created() { this.load(); },
  methods: {
    can(permission) { return hasPermission(this.$store.state.userInfo, permission); },
    async load() { this.loading = true; this.error = ''; try { const [result, approvals] = await Promise.all([platformRequest('GET','/otaMag',{ page: this.page, limit: 20 }), platformRequest('GET','/ops/approvals')]); this.rows = result.list || []; this.total = result.total || 0; this.approvals = (Array.isArray(approvals) ? approvals : approvals.list || []).filter(row => row.action === 'ota.publish'); } catch (error) { this.error = error.message; } finally { this.loading = false; } },
    changePage(page) { this.page = page; this.load(); },
    open() { this.form = { firmwareName: '', type: '', version: '', firmwarePath: '', remark: '', sort: 0 }; this.file = null; this.saveError = ''; this.dialog = true; this.$nextTick(()=>{ if (this.$refs.firmwareFile) this.$refs.firmwareFile.value = ''; }); },
    chooseFile(event) { const file = event.target.files?.[0]; this.file = null; this.form.firmwarePath = ''; if (file && (/\.(bin|apk)$/i.test(file.name) && file.size > 0 && file.size <= 100*1024*1024)) this.file = file; else this.saveError = '请选择不超过 100 MB 的 bin 或 apk 构建产物'; },
    async prepare() { if (this.busy || !this.file) return; if (!this.form.firmwareName.trim() || !this.form.type.trim() || !/^\d+\.\d+\.\d+$/.test(this.form.version)) { this.saveError = '请填写名称、硬件类型和有效版本号'; return; } this.busy = true; this.saveError = ''; try { if (!this.form.firmwarePath) { const data = new FormData(); data.append('file',this.file); this.form.firmwarePath = await platformRequest('POST','/otaMag/upload',data,{ multipart: true }); } const payload = await platformRequest('POST','/otaMag/prepare',this.form); await platformRequest('POST','/ops/approvals',{ action: 'ota.publish', targetId: payload.type, version: payload.version, payload }); this.dialog = false; this.file = null; this.$message.success('固件申请已提交，等待独立审批'); await this.load(); } catch (error) { this.saveError = error.message; } finally { this.busy = false; } },
    async publish(row) { if (this.busy || !this.can('ota.publish')) return; try { await this.$confirm(`发布 ${row.targetId} 的 ${row.version} 批准版本？`, '发布固件', { type: 'warning' }); } catch (_) { return; } this.busy = true; try { const payload = typeof row.payload === 'string' ? JSON.parse(row.payload) : row.payload; await platformRequest('POST','/otaMag',payload,{ headers: { 'X-Ops-Approval-Id': row.id } }); this.$message.success('批准版本已发布'); await this.load(); } catch (error) { this.$message.error(error.message); } finally { this.busy = false; } },
  },
};
</script>
